using System;
using System.Drawing;
using System.Windows.Forms;

private SplitContainer split;
private ListBox lstNav;
private TextBox txtDetails;

public ExampleForm()
{
    Text = "SplitContainer example";
    ClientSize = new Size(420, 240);
    InitializeComponents();
}

split = new SplitContainer();
split.Dock = DockStyle.Fill;
split.FixedPanel = FixedPanel.Panel1;
split.SplitterDistance = 100;

lstNav = new ListBox();
lstNav.Dock = DockStyle.Fill;
lstNav.Items.AddRange(new object[] { "Home", "Settings", "About" });
split.Panel1.Controls.Add(lstNav);

txtDetails = new TextBox();
txtDetails.Multiline = true;
txtDetails.Dock = DockStyle.Fill;
split.Panel2.Controls.Add(txtDetails);

private void Split_SplitterMoved(object sender, SplitterEventArgs e)
{
    Text = "Left panel width: " + split.SplitterDistance;
}

    [STAThread]
    static void Main()
    {
        Application.EnableVisualStyles();
        Application.Run(new ExampleForm());
    }
}

using System;
using System.Drawing;
using System.Windows.Forms;

public ExampleForm()
{
    Text = "FlowLayoutPanel example";
    ClientSize = new Size(360, 160);
    InitializeComponents();
}

flow = new FlowLayoutPanel();
flow.Dock = DockStyle.Fill;
flow.FlowDirection = FlowDirection.LeftToRight;
flow.WrapContents = true;
flow.AutoScroll = true;

for (int i = 1; i <= 8; i++)
{
    Button button = new Button();
    button.Text = "Button " + i;
    button.AutoSize = true;
    flow.Controls.Add(button);
}

    [STAThread]
    static void Main()
    {
        Application.EnableVisualStyles();
        Application.Run(new ExampleForm());
    }
}

using System;
using System.Drawing;
using System.Windows.Forms;

private TableLayoutPanel tlp;
private Label lblName;
private TextBox txtName;
private Button btnOk;

public ExampleForm()
{
    Text = "TableLayoutPanel example";
    ClientSize = new Size(360, 130);
    InitializeComponents();
}

tlp = new TableLayoutPanel();
tlp.Dock = DockStyle.Fill;
tlp.ColumnCount = 2;
tlp.RowCount = 2;
tlp.Padding = new Padding(12);

tlp.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
tlp.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100F));
tlp.RowStyles.Add(new RowStyle(SizeType.AutoSize));
tlp.RowStyles.Add(new RowStyle(SizeType.AutoSize));

lblName = new Label();
lblName.Text = "Name:";
lblName.AutoSize = true;
lblName.Anchor = AnchorStyles.Left;

txtName = new TextBox();
txtName.Anchor = AnchorStyles.Left | AnchorStyles.Right;

btnOk = new Button();
btnOk.Text = "OK";
btnOk.Anchor = AnchorStyles.Right;

tlp.Controls.Add(lblName, 0, 0);
tlp.Controls.Add(txtName, 1, 0);
tlp.Controls.Add(btnOk, 1, 1);

    [STAThread]
    static void Main()
    {
        Application.EnableVisualStyles();
        Application.Run(new ExampleForm());
    }
}
